using Commerce;

namespace ShoppingCart.Tests;

[TestClass]
public class ShoppingCartTests
{
    private Commerce.ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new Commerce.ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 2);

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_AccumulatesTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 5.50m, 3);

        Assert.AreEqual(26.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothEntriesCounted()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-001", 10.00m, 2);

        Assert.AreEqual(30.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_DoesNotAffectTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 0);

        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_RemovesFromTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 2);
        _cart.AddItem("SKU-002", 5.00m, 1);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ReturnsFalse()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsFalse(_cart.RemoveItem("SKU-999"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSkus_RemovesAllEntries()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-001", 10.00m, 2);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal Tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAddAndRemove_ReflectsRemainingItems()
    {
        _cart.AddItem("SKU-001", 15.00m, 2);
        _cart.AddItem("SKU-002", 7.50m, 4);
        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(30.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_LargeQuantity_CalculatesCorrectly()
    {
        _cart.AddItem("SKU-001", 0.01m, 10000);

        Assert.AreEqual(100.00m, _cart.GetTotal());
    }
}

